(8, 1, 'ai', 'app', 'Dear Alice Smith (Sudden Drop),

We noticed changes in your recent attendance patterns. Based on our diagnostic analysis, this irregularity appears consistent with Health Issue (state: Concerned).

Key contributing factors identified:
• Negative recent attendance trend

Recommended next steps:
Empathize with their health condition. Suggest resting and visiting a doctor. Offer flexibility with deadlines.

Please know that your mentors and teachers are here to support your success without penalty. Please reply directly to this message so we can discuss the best way to support you.

Warm regards,
Academic Mentorship & Counselling Team', '2026-10-10 18:52:24'),
