(13, 1, 'student', 'app', 'I cannot attend 1st period daily due to transportation issues', '2026-10-10 19:23:25'),
(14, 1, 'ai', 'app', 'Dear Alice,

Thank you for letting me know about your transportation issues. I can imagine how frustrating that must be, especially when you''ve been unwell recently. If it’s making it hard for you to attend the first period, have you thought about any alternative arrangements or support that might help? 

We certainly want to make sure you don’t fall behind, especially since you''ve been dealing with your health concerns too. Maybe communicating with your teacher about your situation could offer some options, or we can look into resources that could assist you with transport. How do you feel about maybe committing to attending just your second period for now until we sort this out? That way, you can still keep your attendance on track a little while longer.

I’m here for you, so please share any thoughts you have. 

Warm regards,  
Your Counsellor', '2026-10-10 19:23:25');

-- Data for chatbot_logs (5 rows)
INSERT INTO `chatbot_logs` (`id`, `student_id`, `question`, `answer`, `created_at`) VALUES
(1, 1, 'Hi', 'Hello! How can I assist you today?', '2026-10-10 19:24:26'),
(2, 1, 'I am playing uno, tell me the rules to play', 'Uno is a fun and easy card game played with a specially printed deck. Here are the basic rules to get you started:

### Objective:
Be the first player to score 500 points. Score points by being the first to get rid of all your cards in each round.

### Setup:
1. **Players:** Typically played with 2-10 players.
2. **Deck:** The Uno deck consists of 108 cards: 
   - 76 number cards (0-9) in four colors (red, yellow, green, blue).
   - 8 Skip cards (2 in each color).
   - 8 Reverse cards (2 in each color).
   - 8 Draw Two cards (2 in each color).
   - 4 Wild cards.
   - 4 Wild Draw Four cards.

3. **Dealing Cards:** Shuffle the deck and deal 7 cards to each player. Place the remaining cards face down to form a draw pile. Flip over the top card to start the discard pile.

### Gameplay:
1. **Starting the Game:** The player to the left of the dealer plays first by matching a card from their hand to the card on the discard pile by number, color, or symbol.
  
2. **Playing Cards:** 
   - You can play a number card that matches the top card of the discard pile or a card of the same color.
   - Special cards:
     - Skip: Next player loses their turn.
     - Reverse: Reverses the order of play.
     - Draw Two: Next player must draw two cards and lose their turn.
     - Wild: Can play at any time and change the current color.
     - Wild Draw Four: Can be played if you have no cards matching the current color; the next player draws four cards and loses their turn (can be challenged).

3. **Drawing Cards:** If you can''t play a card, you must draw one from the draw pile. If you can play it, you may; otherwise, your turn ends.

4. **Uno Call:** When you have only one card left, you must yell "Uno!" If another player catches you not saying it before your next turn, you must draw two cards as a penalty.

5. **Ending the Round:** The round ends when a player plays their last card. Points are scored based on the cards left in the opponents'' hands:
   - Number cards: Face value.
   - Skip, Reverse, Draw Two: 20 points each.
   - Wild, Wild Draw Four: 50 points each.

### Winning the Game:
Continue playing rounds until a player reaches 500 points.

Enjoy your game of Uno!', '2026-10-10 19:25:20'),
